#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    if (n > m) {
        swap(n, m);
    }
    if (n == 1) {
        cout << ((m / 6) + ((m + 1) / 6) + ((m + 2) / 6)) * 2 << endl;
    } else if (n == 2) {
        if (m == 2) {
            cout << 0 << endl;
        } else if (m == 3) {
            cout << 4 << endl;
        } else if (m == 7) {
            cout << 12 << endl;
        } else {
            cout << n * m << endl;
        }
    } else {
        cout << (n * m) / 2 * 2 << endl;
    }
    return 0;
}
